<template><div><h1 class="mb-6 text-2xl font-bold">게시글 관리</h1><div class="rounded bg-white shadow"><RouterLink v-for="b in page?.content" :key="b.id" :to="`/admin/boards/${b.id}`" class="block border-b p-5"><b>{{b.title}}</b><span class="ml-3 text-sm text-slate-500">{{b.writerName}}</span></RouterLink></div><Pagination :page="page" @change="load"/></div></template>
<script setup>import{onMounted,ref}from'vue';import{adminApi}from'../../api/adminApi';import Pagination from'../../components/Pagination.vue';const page=ref(null);async function load(p=0){page.value=(await adminApi.boards({page:p,size:10})).data}onMounted(load)</script>